 uint32_t settingsWrite()const{using S=PanelSettingsTask::Stage;const auto*t=settingsTask();if(!t)return 0;switch(t->stage()){case S::WriteCopyByte:return 0x158ec+t->position();case S::WriteSelectedMode:return 0x158f2;case S::WriteDuty:return 0x158f0;default:return 0x159f0;}}
