 void eventsEffect(){if(const auto*p=events_->panelTask()){using S=PanelInputTask::Stage;const auto s=p->stage();effect_.write=s==S::SavePop||s==S::SavePopAux||s==S::ConvertControl;effect_.read=s==S::RestoreEmpty||s==S::RestorePopAux||s==S::RestorePop||s==S::ReturnEmpty||s==S::ReturnPop;}if(const auto*a=events_->analogTask()){using S=PanelAnalogTask::Stage;switch(a->stage()){case S::RetainSpan:case S::SaveFirstAddress:case S::SaveFirstBias:case S::SaveSecondAddress:case S::SaveSecondBias:case S::SaveValue:case S::SaveSquare:case S::ScaleFirst:case S::ScaleSecond:effect_.write=true;break;case S::RestoreSpan:case S::RestoreFirstBias:case S::RestoreFirstAddress:case S::RestoreSecondBias:case S::RestoreSecondAddress:case S::RestoreValue:case S::RestoreSquare:case S::ReturnCoefficients:case S::ReturnRange:case S::ReturnUnchanged:case S::ReturnFirst:case S::ReturnSecond:case S::ReturnValue:case S::ReturnSquare:effect_.read=true;break;default:break;}}}
