 std::array<std::optional<Frame>,2>frames_{};unsigned count_=0;std::optional<StateEventsService>events_;std::optional<PanelSettingsLcdService>display_;std::optional<PanelControlsService>controls_;std::optional<PanelAnalogTask>analog_;std::optional<StateSavePageService>flash_;std::optional<PanelAdcScanTask>warmup_;std::optional<PanelAdcCalibrationTask>snapshot_;std::optional<PanelInputTask>reset_;
